"use client"

import { Check, Copy, XCircle } from "lucide"
import { MorphIcon } from "morphicons/react"
import * as React from "react"

import { Button } from "@/components/ui/button"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { AnchoredToastProvider, ToastPrimitive } from "@/components/ui/toast"
import type { CopyState } from "@/hooks/use-copy-to-clipboard"
import { useCopyToClipboard } from "@/hooks/use-copy-to-clipboard"
import { cn } from "@/lib/utils"

export interface CopyStateIconProps {
  state: CopyState
  idleIcon?: React.ReactNode
  doneIcon?: React.ReactNode
  errorIcon?: React.ReactNode
}

export function CopyStateIcon({
  state,
  idleIcon,
  doneIcon,
  errorIcon,
}: CopyStateIconProps) {
  if (state === "idle" && idleIcon) return idleIcon
  if (state === "done" && doneIcon) return doneIcon
  if (state === "error" && errorIcon) return errorIcon

  return (
    <MorphIcon
      icon={state === "done" ? Check : state === "error" ? XCircle : Copy}
      spring="snappy"
      className="size-4"
    />
  )
}

export interface CopyButtonProps extends React.ComponentProps<typeof Button> {
  text: string | (() => string)
  label?: string
  /**
   * Toast manager the "copied" feedback anchors to. By default CopyButton
   * brings its own manager and provider, so it works with zero setup. Pass
   * your app's own manager (alongside a matching ancestor
   * `AnchoredToastProvider`) only if you want this button's confirmation to
   * share state with other anchored toasts elsewhere on the page.
   */
  toastManager?: ReturnType<typeof ToastPrimitive.createToastManager>
  /** Which side of the button the confirmation toast anchors to. @default "top" */
  side?: NonNullable<ToastPrimitive.Positioner.Props["side"]>
  onCopySuccess?: (text: string) => void
  onCopyError?: (error: Error) => void
  idleIcon?: React.ReactNode
  doneIcon?: React.ReactNode
  errorIcon?: React.ReactNode
}

/**
 * An icon button that copies `text` to the clipboard, morphs its icon to
 * reflect the result, and anchors a toast to itself confirming the copy —
 * self-contained, no `AnchoredToastProvider` wrapper needed.
 */
export function CopyButton({
  className,
  size = "icon",
  children,
  text,
  label = "کپی",
  toastManager,
  side = "top",
  idleIcon,
  doneIcon,
  errorIcon,
  onClick,
  onCopySuccess,
  onCopyError,
  ...props
}: CopyButtonProps) {
  const ref = React.useRef<HTMLButtonElement>(null)
  const timeout = 2000
  const ownManager = React.useMemo(
    () => ToastPrimitive.createToastManager(),
    []
  )
  const manager = toastManager ?? ownManager

  const { state, copy } = useCopyToClipboard({
    resetDelay: timeout,
    onCopySuccess: (copied) => {
      if (ref.current) {
        manager.add({
          title: "کپی شد!",
          timeout,
          positionerProps: { anchor: ref.current, side },
        })
      }
      onCopySuccess?.(copied)
    },
    onCopyError: (error) => {
      if (ref.current) {
        manager.add({
          title: "خطا در کپی",
          type: "error",
          timeout,
          positionerProps: { anchor: ref.current, side },
        })
      }
      onCopyError?.(error)
    },
  })

  const button = (
    <Tooltip>
      <TooltipTrigger
        render={
          <Button
            ref={ref}
            className={cn("will-change-transform", className)}
            size={size}
            aria-label={label}
            onClick={(event) => {
              copy(typeof text === "function" ? text() : text)
              onClick?.(event)
            }}
            {...props}
          >
            <CopyStateIcon
              state={state}
              idleIcon={idleIcon}
              doneIcon={doneIcon}
              errorIcon={errorIcon}
            />
            {children}
          </Button>
        }
      />
      <TooltipContent sideOffset={8}>{label}</TooltipContent>
    </Tooltip>
  )

  if (toastManager) {
    return button
  }

  return (
    <AnchoredToastProvider toastManager={ownManager}>
      {button}
    </AnchoredToastProvider>
  )
}

"use client"

import * as React from "react"

export type CopyState = "idle" | "done" | "error"

function legacyCopy(value: string) {
  const textArea = document.createElement("textarea")
  textArea.value = value
  textArea.setAttribute("readonly", "")
  textArea.style.position = "fixed"
  textArea.style.opacity = "0"
  textArea.style.pointerEvents = "none"

  document.body.appendChild(textArea)
  textArea.focus()
  textArea.select()
  textArea.setSelectionRange(0, value.length)

  let hasCopied = false
  try {
    hasCopied = document.execCommand("copy")
  } catch {
    hasCopied = false
  }

  document.body.removeChild(textArea)
  return hasCopied
}

export interface UseCopyToClipboardOptions {
  /** Delay before `state` resets back to `"idle"`, in ms. @default 2000 */
  resetDelay?: number
  onCopySuccess?: (text: string) => void
  onCopyError?: (error: Error) => void
}

/** Copies text to the clipboard, exposing an idle/done/error state for UI feedback. */
export function useCopyToClipboard({
  resetDelay = 2000,
  onCopySuccess,
  onCopyError,
}: UseCopyToClipboardOptions = {}) {
  const [state, setState] = React.useState<CopyState>("idle")
  const resetTimeout = React.useRef<ReturnType<typeof setTimeout>>(undefined)

  const copy = React.useCallback(
    async (value: string) => {
      window.clearTimeout(resetTimeout.current)

      try {
        if (navigator.clipboard?.writeText) {
          await navigator.clipboard.writeText(value)
        } else if (!legacyCopy(value)) {
          throw new Error("Copy command was not successful")
        }

        setState("done")
        onCopySuccess?.(value)
      } catch (err) {
        setState("error")
        onCopyError?.(err instanceof Error ? err : new Error(String(err)))
      }

      if (resetDelay !== 0) {
        resetTimeout.current = setTimeout(() => setState("idle"), resetDelay)
      }
    },
    [onCopyError, onCopySuccess, resetDelay]
  )

  React.useEffect(() => () => window.clearTimeout(resetTimeout.current), [])

  return { state, copy }
}
